"""Run outside a checkout with the built wheel and its ACP extra installed."""

from __future__ import annotations

import asyncio
import os
import shutil
import sys
import tempfile
from pathlib import Path

from acp import RequestError, spawn_agent_process


class Client:
    async def session_update(self, **kwargs):
        raise AssertionError("No prompt was sent")


async def main() -> None:
    # The command under test: `strandly`, or a CLI generated by `strandly cli build`.
    command = shutil.which(sys.argv[1] if len(sys.argv) > 1 else "strandly")
    assert command is not None
    with tempfile.TemporaryDirectory() as home:
        async with spawn_agent_process(
            Client(),
            command,
            "acp",
            cwd=home,
            env={**os.environ, "HOME": home},
        ) as (agent, _):
            result = await agent.initialize(protocol_version=1)
            assert result.protocol_version == 1
            assert result.agent_info.name == "strandly-remote"
            assert not result.agent_capabilities.load_session
            try:
                await agent.new_session(cwd=str(Path(home)))
            except RequestError as exc:
                assert exc.code == -32000
            else:
                raise AssertionError("Clean home must require login")
    print("ACP wheel / official reference client / stdio: ok")


if __name__ == "__main__":
    asyncio.run(main())
